"""Track 2 scorer (organiser code). Rules come from rules.json, generated by build.py.

Inputs (from the harness): predictions_test_<run>.jsonl for each timed run, predictions_dev.jsonl, metadata.json.
Writes /app/output/scores.json (leaderboard columns) and /app/output/details.json (per run, task, source, crop).

Ranking uses test only: quality = the LOWEST test quality over the timed runs (a run cannot be traded for speed),
wall time = the harness's median. Eligible if, in every timed run, each task's test mean (text, table, formula)
is at or above its own line (rules.json "min_quality"); the per-task columns show each task's lowest run.
rank_key = wall_time if eligible else 1e6 + wall_time  (lower is better; hidden column that sorts the board).
Dev and dev+test quality are shown for information.
"""
import glob
import json
import os
import re
import subprocess
import sys
import tempfile
from collections import defaultdict

HERE = os.path.dirname(os.path.abspath(__file__))
# Per-crop metrics come from GravityOCR's own scorer (trida-stack), run in the image's evaluation venv.
EVAL_PYTHON = os.path.join(os.environ.get("GRAVITYOCR_EVAL", "/opt/gravityocr-eval"), "venv", "bin", "python")

REF = os.environ.get("TRACK2_REF", "/app/input/ref/reference.jsonl")
RES = os.environ.get("TRACK2_RES", "/app/input/res")
OUT = os.environ.get("TRACK2_SCORE_OUT", "/app/output")

RULES = json.load(open(os.path.join(HERE, "rules.json")))
TASKS = ("text", "table", "formula")


def load_preds(path):
    pred = {}
    if os.path.exists(path):
        for line in open(path):
            if line.strip():
                r = json.loads(line)
                pred[str(r.get("id"))] = str(r.get("text", ""))
    return pred


def score_all(sets):
    """sets: {key: (refs, preds)} -> {key: rows}. One call to trida_metrics.py scores every prediction set."""
    tmp = tempfile.mkdtemp(prefix="track2_score_")
    jobs, out = os.path.join(tmp, "jobs.jsonl"), os.path.join(tmp, "scores.json")
    with open(jobs, "w", encoding="utf-8") as f:
        for key, (refs, preds) in sets.items():
            for r in refs:     # a missing prediction is scored as ""
                f.write(json.dumps({"key": key, "id": r["id"], "task": r["task"], "target": r["target"],
                                    "pred": preds.get(r["id"], "")}, ensure_ascii=False) + "\n")
    # CDM runs team LaTeX: keep the answers root-only (the scorer checks, and refuses to score if they are not).
    # Every parent of the reference is made root-only where possible: /app/input/ref may be a read-only mount, but
    # /app is on the container's own filesystem. The LaTeX sandbox needs nothing under it.
    ref_dir = os.path.dirname(os.path.abspath(REF))
    d, locked = ref_dir, False
    while d not in ("/", tempfile.gettempdir()):
        try:
            os.chmod(d, 0o700)
            locked = True
        except OSError:
            pass
        d = os.path.dirname(d)
    if not locked:
        print(f"could not lock any parent of {ref_dir}; trida_metrics.py checks what the sandbox can read")
    subprocess.run([EVAL_PYTHON, os.path.join(HERE, "trida_metrics.py"), jobs, out, REF, ref_dir], check=True)
    got = json.load(open(out))
    return {key: [{"id": r["id"], "split": r["split"], "task": r["task"], "source": r["source"],
                   "score": got[key][r["id"]]} for r in refs] for key, (refs, _) in sets.items()}


def aggregate(rows):
    """rows: [{"task", "source", "score"}] -> quality (mean of the task means, as trida-stack's Overall), per task."""
    by_task, by_source = defaultdict(list), defaultdict(list)
    for r in rows:
        by_task[r["task"]].append(r["score"])
        by_source[r["source"]].append(r["score"])
    task_means = {t: sum(v) / len(v) for t, v in by_task.items()}
    return {"quality": sum(task_means.values()) / len(task_means) if task_means else 0.0,
            "per_task": task_means,
            "per_source": {k: sum(v) / len(v) for k, v in sorted(by_source.items())},
            "counts": {t: len(v) for t, v in by_task.items()}}


def gate(runs, lines):
    """runs: [{task: mean}] per timed run; lines: {task: minimum} -> ({task: lowest over runs}, eligible).
    A task with no score in a run counts as 0. Compared at the 2 decimals the board shows."""
    worst = {t: min(float(r.get(t, 0.0)) for r in runs) for t in lines}
    return worst, all(pass_flags(worst, lines).values())


def pass_flags(worst, lines):
    """{task}_pass = 1 if the task's lowest run is at or above its line (at the board's 2 decimals), else 0.
    Used for eligibility only; the board shows the scores themselves."""
    return {f"{t}_pass": int(round(worst[t], 2) >= float(lines[t])) for t in lines}


def main():
    refs = [json.loads(l) for l in open(REF) if l.strip()]
    test_refs = [r for r in refs if r["split"] == "test"]
    dev_refs = [r for r in refs if r["split"] == "dev"]

    runs = sorted(glob.glob(os.path.join(RES, "predictions_test_*.jsonl")),
                  key=lambda p: int(re.search(r"_(\d+)\.jsonl$", p).group(1)))
    if not runs:
        sys.exit("no predictions_test_*.jsonl from the harness")
    preds = {os.path.basename(p): load_preds(p) for p in runs}
    dev_preds = load_preds(os.path.join(RES, "predictions_dev.jsonl"))
    scored = score_all({**{k: (test_refs, v) for k, v in preds.items()}, "dev": (dev_refs, dev_preds)})
    per_run = []
    for path in runs:
        name = os.path.basename(path)
        rows = scored[name]
        per_run.append({"file": name, "rows": rows, "agg": aggregate(rows),
                        "missing": sum(1 for r in test_refs if r["id"] not in preds[name])})
    worst = min(per_run, key=lambda r: r["agg"]["quality"])

    dev_rows = scored["dev"]
    dev_agg = aggregate(dev_rows)
    combined = aggregate(worst["rows"] + dev_rows)

    meta = json.load(open(os.path.join(RES, "metadata.json")))
    wall = float(meta["wall_time"])
    quality = worst["agg"]["quality"]
    lines = RULES["min_quality"]
    task_worst, eligible = gate([r["agg"]["per_task"] for r in per_run], lines)

    scores = {
        "rank_key": round(wall if eligible else 1e6 + wall, 3),
        "quality": round(quality, 2),
        "wall_time": round(wall, 3),
        "eligible": 1 if eligible else 0,
        "combined": round(combined["quality"], 2),
        "dev": round(dev_agg["quality"], 2),
        **{t: round(task_worst.get(t, 0.0), 2) for t in TASKS},
        "missing": worst["missing"],
    }
    os.makedirs(OUT, exist_ok=True)
    json.dump(scores, open(os.path.join(OUT, "scores.json"), "w"))
    details = {
        "rules": RULES, "timing": meta,
        "test_runs": [{"file": r["file"], "quality": r["agg"]["quality"], "per_task": r["agg"]["per_task"],
                       "missing": r["missing"]} for r in per_run],
        # Teams see this file in their logs: test is reported per task only, never per crop or per source.
        "dev": {**dev_agg, "crops": dev_rows},
        "combined": {k: combined[k] for k in ("quality", "per_task", "counts")},
    }
    json.dump(details, open(os.path.join(OUT, "details.json"), "w"), ensure_ascii=False, indent=1)

    print("lines:", lines, "lowest per task:", {t: round(v, 2) for t, v in task_worst.items()})
    print("test quality per run:", [round(r["agg"]["quality"], 2) for r in per_run])
    print("scores:", scores)


if __name__ == "__main__":
    main()
